const { Fragment, jsx, jsxs } = arguments[0];
function _missingMdxReference(name) { throw new Error("Component <" + name + "> was not provided via the MDX components prop. Register it in your component map."); }
function _createMdxContent(props) {
  const _components = { a: "a", code: "code", div: "div", h2: "h2", h3: "h3", hr: "hr", li: "li", p: "p", pre: "pre", span: "span", strong: "strong", table: "table", tbody: "tbody", td: "td", th: "th", thead: "thead", tr: "tr", ul: "ul", ...props.components };
  const { Callout, MermaidDiagram, Zap } = _components;
  if (!Callout) _missingMdxReference("Callout");
  if (!MermaidDiagram) _missingMdxReference("MermaidDiagram");
  if (!Zap) _missingMdxReference("Zap");
  return jsxs(Fragment, { children: [jsxs(Callout, { icon: jsx(Zap, {  }), children: ["  ", jsx(_components.code, { children: "duck-template" }), " scaffolds projects from JSON configs. It supports ", jsx(_components.strong, { children: "variants" }), ", ", jsx(_components.strong, { children: "remote configs" }), " (fetched over HTTP), and ", jsx(_components.strong, { children: "dynamic flag injection" }), " into template files."] }), jsx(MermaidDiagram, { chart: "flowchart TD
